https://atcoder.jp/contests/abc450/tasks/abc450_d

思路：可以发现差值应该是和余数有关的，然后就可以考虑把每个元素%k，然后排序，每次更改的时候要么是更改最大的或者最小的，%k之后所有数的差值不超过k-1，所以一个数加上k，必然是最大的，然后呢，一旦我选择了更改最小值，那么我之后都是选择更改最小值，因为最小值已经变成最大值，我更改最大值就只是撤销操作而已，那么需不需要一开始更改最大值呢，答案是不需要因为一个元素-k，等于其他剩余元素都+k，所以更改最小值已经包含了更改最大值的情况

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n, k;
    cin >> n >> k;
    vt<ll> a(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] %= k;
    }
    sort(rg(a, 1, n));
    deque<ll> q;
    for (int i = 1; i <= n; i++) {
        q.push_back(a[i]);
    }
    ll ans = a[n] - a[1];
    for (int i = 1; i < n; i++) {
        ll x = q.front();
        q.pop_front();
        x += k;
        q.push_back(x);
        ans = min(ans, q.back() - q.front());
    }
    cout << ans << "\n";
    return 0;
}
```

https://ac.nowcoder.com/acm/contest/130843/E

听说这是经典题，区间dp能做，但是时间复杂度是n^4，改成线性dp又能做了，思路就是如果第i个格子被染色了，则一定存在一个操作区间右端点是i，那么我们只需要枚举右端点，然后剩下的就是在[l - 1, i - 1]这个区间里面选最小的dp

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

void solve() {
    int n;
    cin >> n;
    vt<int> a(n + 5), pref(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        pref[i] = pref[i - 1] ^ a[i];
    }
    vt<ll> dp(n + 5, 1e18);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        ll mn = 1e18;
        for (int l = i; l >= 1; l--) {
            mn = min(mn, dp[l - 1]);
            dp[i] = min(dp[i], mn + (pref[i] ^ pref[l - 1]));
        }
    }
    cout << dp[n] << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

https://ac.nowcoder.com/acm/contest/130843/E

会发现m和M都应该出现在区间端点的位置，也就是m = a[l], M = a[r]或者m = a[r], M = a[l]，然后写成f(r) + f(l)的形式就行了

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

/*
M - m - r + l

(M - m) - (r - l)

m = a[l], M = a[r]

a[r] - a[l] - r + l
a[r] - r - (a[l] - l)

M = a[l], m = a[r]

a[l] - a[r] - r + l
(a[l] + l) - (a[r] + r)
*/

void solve() {
    int n;
    cin >> n;
    int ans = 0;
    int mn = 1e9, mx = -1e9;
    for (int i = 1; i <= n; i++) {
        int a;
        cin >> a;
        int t1 = a + i;
        int t2 = a - i;
        mn = min(mn, t2);
        mx = max(mx, t1);
        ans = max({ans, mx - t1, t2 - mn});
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        solve();
    }
    return 0;
}
