https://codeforces.com/contest/2211/problem/C2

这题根本就难到飞起，怎么可能有3000+人过的，说一下思路，我们考虑[l, r]到[l+1, r+1]之间发生的变化

我们假设a[l, r]的元素集合为A，b[l, r]元素集合为B

根据题目要求，我们要A=B

好，我们就假设A=B

变化到[l+1, r+1]的时候

A = A - {a[l]} + {a[r+1]}

B = B - {b[l]} + {b[r+1]}

考虑两种两种情况

(1) a[l] = a[r+1]

要使得A=B，那么b[l] = b[r+1]

(2) a[l] != a[r+1]

那么a[l] = b[l], a[r+1] = b[r+1]

l和r+1相差k，我们按照同余的坐标分类

如果同一个同余类里面有两个a[i]不同，那么这个同余类的所有b[i]和a[i]是相等的

否则，这个同余类只需要满足所有b[i]是相等的

做完这个过程我们需要判断[1, k]这个区间是否满足条件，过程我们已经确定没有问题了，只要初始条件没有问题，答案就没有问题，[1, k]每个坐标都属于不同的同余类，我们可以自由分配值

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define ts cerr << "line: " << __LINE__ << endl
#else
#define db(x) 114514
#define el 1919810
#define ts 42
#endif

void solve() {
    int n, k;
    cin >> n >> k;
    vt<int> a(n + 5), b(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }
    for (int i = 1; i <= k; i++) {
        bool all_same = true;
        for (int j = i; j <= n; j += k) {
            if (a[j] != a[i]) {
                all_same = false;
            }
        }
        if (!all_same) {
            for (int j = i; j <= n; j += k) {
                if (b[j] != -1 && b[j] != a[j]) {
                    cout << "NO\n";
                    return;
                }
                b[j] = a[j];
            }
        } else {
            int val = -1;
            for (int j = i; j <= n; j += k) {
                if (b[j] != -1) {
                    val = b[j];
                    break;
                }
            }
            for (int j = i; j <= n; j += k) {
                if (b[j] != -1 && b[j] != val) {
                    cout << "NO\n";
                    return;
                }
                b[j] = val;
            }
        }
    }
    // for (int i = 1; i <= n; i++) {
    //     cout << b[i] << " \n"[i == n];
    // }
    vt<int> cnta(n + 5);
    for (int i = 1; i <= k; i++) {
        cnta[a[i]]++;
    }
    vt<int> cntb(n + 5);
    for (int i = 1; i <= k; i++) {
        if (b[i] != -1 && i <= k) {
            cntb[b[i]]++;
        }
    }
    for (int i = 1; i <= k; i++) {
        if (b[i] != -1 && cntb[b[i]] > cnta[b[i]]) {
            cout << "NO\n";
            return;
        }
    }
    cout << "YES\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

https://codeforces.com/contest/2211/problem/D

这题确实比C2简单，但是还是很难，首先我们考虑b[i]是怎么确定的

$$
b_i = \sum_{j=0}^{30} {\binom{cnt_j}{i} \cdot 2^{j}}
$$

可以看到b[i]的值只和cnt[j]有关系，和这些1在哪个a[i]是没有关系的，我们只需要知道每个cnt[j]的值就能够构造出一个a

观察b[n]，发现只有cnt[j]==n时才有贡献，通过检查b[n]的二进制位我们就可以知道某些cnt[j]的值，然后减去这个cnt[j]对b[n-1]的贡献，然后就可以通过同样的方法知道cnt[j]==n-1的那些j，因为我们遍历了n~1的所有值，所以我们肯定能够知道所有cnt[j]的值

另外还有一点，在减去贡献的时候我们可能会想说b[i]已经取过模了，我们还能够判断它的二进制位吗，当我们减去其他cnt[j] > i的贡献的时候，剩下能产生贡献的必然是cnt[j] == i的，而它们最大的贡献就是C(i, i) \* 2 ^ j，不会超过MOD，所以是等价于没有取模过的

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define ts cerr << "line: " << __LINE__ << endl
#else
#define db(x) 114514
#define el 1919810
#define ts 42
#endif

const ll MOD = 1e9 + 7;
vector<ll> fac, inv_fac;

ll power(ll u, ll v) {
    ll res = 1;
    while (v) {
        if (v % 2) res = res * u % MOD;
        u = u * u % MOD;
        v /= 2;
    }
    return res;
}

void combInit(int n) {
    fac.resize(n + 1);
    inv_fac.resize(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = fac[i - 1] * i % MOD;
    }
    inv_fac[n] = power(fac[n], MOD - 2);
    for (int i = n - 1; i >= 0; i--) {
        inv_fac[i] = inv_fac[i + 1] * (i + 1) % MOD;
    }
}

ll C(int n, int k) {
    if (n < k) {
        return 0;
    }
    return (fac[n] * inv_fac[k] % MOD) * inv_fac[n - k] % MOD;
}

void solve() {
    int n;
    cin >> n;
    vt<ll> b(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
    }
    vt<int> cnt(30);
    for (int i = n; i >= 1; i--) {
        for (int j = 0; j < 30; j++) {
            if (cnt[j] > i) {
                b[i] -= C(cnt[j], i) * power(2, j) % MOD;
                if (b[i] < 0) {
                    b[i] += MOD;
                }
            }
        }
        for (int j = 0; j < 30; j++) {
            if (b[i] >> j & 1) {
                cnt[j] = i;
            }
        }
    }
    vt<int> a(n + 5);
    for (int j = 0; j < 30; j++) {
        for (int i = 1; i <= cnt[j]; i++) {
            a[i] += 1 << j;
        }
    }
    for (int i = 1; i <= n; i++) {
        cout << a[i] << " \n"[i == n];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    combInit(1e5);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

https://codeforces.com/contest/2209/problem/C

思路：应该会很自然的想到询问所有的(2k-1,2k)对，就能保证这些对里面都仅有一个0，然后询问(1,3),(1,4)，但是这样是n+2次操作，想想有没有操作是没有必要的，其实(1,2)是没有必要的，假设我们做了以上的询问，然后没有问(1,2)，再假设a[1]和a[2]都不等于0，也就是说有n个0在n-1个对里面，根据抽屉原理至少有一对有两个0，有矛盾，如果a[1]=0,a[2]!=0，这代表a[3]和a[4]不等于0，也就是说有n-1个0在n-2个对里面，同理矛盾，a[1]=0,a[2]=0，这个是没有问题的，a[1]!=0,a[2]=0，其实这个情况也会有矛盾，然后总结就是如果全部询问都是0，那么a[2]就是0

代码：

```cpp
