https://ac.nowcoder.com/acm/contest/130107/E

思路：以为是思维，没想到是树上dp，dp[i]表示节点i是否是一个好点，叶子结点是好点，另外一种就是能到达至少两个好点的点也是一个好点，因为小紫能封堵小红后续的一个点，所以如果小红后续只有一个好点，小紫直接把这个点封掉就是了，所以至少需要两个，小红往回走是浪费时间，所以只需要考虑子节点，所以dp是成立的

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

void solve() {
    int n;
    cin >> n;
    vt<vt<int>> adj(n + 5);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].pb(v);
        adj[v].pb(u);
    }
    vt<bool> dp(n + 5);
    auto dfs = [&](auto &&self, int u, int p) -> void {
        int cnt = 0;
        bool has_son = false;
        for (int v : adj[u]) {
            if (v == p)
                continue;
            self(self, v, u);
            cnt += dp[v];
            has_son = true;
        }
        if (!has_son)
            dp[u] = true;
        if (cnt >= 2)
            dp[u] = true;
    };
    dfs(dfs, 1, 0);
    for (int v : adj[1]) {
        if (dp[v]) {
            cout << "red\n";
            return;
        }
    }
    cout << "purple\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
