https://ac.nowcoder.com/acm/contest/129583/C

思路：假设我选择两个大猴子，能满意的小猴子数量应该是k[x]-k[y]-jj(x,y)，jj是交集，这里就是jj这个预处理要想到，用map来实现，然后没有交集的，也要点手法，就是如果发现所有jj集合的数量没有满的话，那必然存在没有交集的两个大猴子

代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vt<int> k(m + 5);
    map<pair<int, int>, int> mp;
    for (int i = 1; i <= n; i++) {
        int a, b;
        cin >> a >> b;
        if (a > b) {
            swap(a, b);
        }
        k[a]++, k[b]++;
        mp[{a, b}]++;
    }
    for (int i = 1; i <= m; i++) {
        db(i), db(k[i]), el;
    }
    vt<int> ks;
    vt<int> cnt(n + 5);
    for (int i = 1; i <= m; i++) {
        ks.pb(k[i]);
        cnt[k[i]]++;
    }
    sort(all(ks), greater<>());
    int ans = 0;
    if (cnt[ks[0]] == 1) {
        int cnt2=0;
        for (auto [_, __] : mp) {
            int x = _.first;
            int y = _.second;
            if (k[x] < k[y]) {
                swap(x, y);
            }
            if (k[x] == ks[0] && k[y] == ks[1]) {
                cnt2++;
                if (x > y) {
                    swap(x, y);
                }
                ans = max(ans, k[x] + k[y] - mp[{x, y}]);
            }
        }
        if(cnt2<1LL*cnt[ks[0]]*cnt[ks[1]]){
            ans=max(ans,ks[0]+ks[1]);
        }
    } else {
        int cnt2=0;
        for (auto [_, __] : mp) {
            int x = _.first;
            int y = _.second;
            if (k[x] == ks[0] && k[y] == ks[0]) {
                cnt2++;
                ans = max(ans, k[x] + k[y] - mp[{x, y}]);
            }
        }
        if(cnt2<1LL*cnt[ks[0]]*(cnt[ks[0]]-1)/2){
            ans=max(ans,ks[0]*2);
        }
    }
    cout << ans << "\n";
    return 0;
}
```

# Squarepoint Challenge (Codeforces Round 1055, Div. 1 + Div. 2)

## D

思路：要考虑什么时候才会使得A的操作数增加1，就是当那个数是全1的形式

100001，末尾的1直接被A先干掉，没救了

110001，末尾的1，先被A干掉，后续可以不操作，直到1再次出现在个位，直接加1

1000100001，同样地，等1出现在个位，+1可以给这个1续命，最后必然会有一堆1连在一起

所以说，有两个1的能产生贡献，但是仅有两个1的且有一个1在个位的可能会被干掉，假设这样的数有x个，A干一个，B救一个

A能干掉(x+1)/2个，B救x/2个

代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()
#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

void solve() {
    int n, q;
    cin >> n >> q;
    vt<int> a(n + 5);
    vt<int> pref1(n + 5), pref2(n + 5), pref3(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        // bitset<10> b = a[i];
        // db(b), el;
        pref1[i] = pref1[i - 1] + (__builtin_popcount(a[i]) >= 2);
        pref2[i] = pref2[i - 1] + (__builtin_popcount(a[i]) == 2 && a[i] % 2 == 1);
        pref3[i] = pref3[i - 1];
        int x = a[i];
        while (x > 1) {
            x /= 2;
            pref3[i]++;
        }
    }
    while (q--) {
        int l, r;
        cin >> l >> r;
        int ans = pref3[r] - pref3[l - 1];
        // db(ans), el;
        int cnt1 = pref1[r] - pref1[l - 1];
        int cnt2 = pref2[r] - pref2[l - 1];
        cnt2 = (cnt2 + 1) / 2;
        cnt1 -= cnt2;
        ans += cnt1;
        cout << ans << "\n";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

