# Codeforces Round 1056 (Div. 2)

## C

思路：考虑从位置i走到位置i+1的变化情况

有四种：

(1) ((
增量为1

(2) ))
增量为-1

(3) ()
增量为0

(4) )(
增量为0

可以发现a[i]-a[i-1]都是<2的，所以>=2的答案为0

其他情况我们这样搞，枚举第一个位置的披风方向，然后通过增量可以推算出每个位置的披风方向，然后我们再去检查整个数组的披风方向是否合法，就是对于每个位置，左边(的总和加上)的总和+1要等于a[i]

代码:

```cpp
#include <bits/stdc++.h>

using namespace std;
using ll = long long;

#define vt vector
#define pb push_back
#define sz(x) int(x.size())
#define rg(x, l, r) x.begin() + l, x.begin() + r + 1
#define all(x) x.begin(), x.end()

#ifdef LOCAL
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#else
#define db(x) 114514
#define el 1919810
#endif

const ll MOD = 676767677;

void solve() {
    int n;
    cin >> n;
    vt<int> a(n + 5);
    bool flag = true;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        if (i >= 2) {
            if (abs(a[i] - a[i - 1]) >= 2) {
                flag = false;
            }
        }
    }
    if (!flag) {
        cout << "0\n";
        return;
    }
    auto check = [&](int first) -> bool {
        string s;
        s += first ? ')' : '(';
        for (int i = 2; i <= n; i++) {
            int d = a[i] - a[i - 1];
            if (!d) {
                s += s.back() == '(' ? ')' : '(';
            } else if (d == 1) {
                // ((
                if (s.back() == ')')
                    return false;
                s += '(';
            } else {
                // ))
                if (s.back() == '(')
                    return false;
                s += ')';
            }
        }
        // assert(sz(s) == n);
        // db(s), el;
        s = ' ' + s;
        vt<int> pref(n + 5);
        for (int i = 1; i <= n; i++)
            pref[i] = pref[i - 1] + (s[i] == '(');
        vt<int> suff(n + 5);
        for (int i = n; i >= 1; i--) {
            suff[i] = suff[i + 1] + (s[i] == ')');
            // db(i), db(suff[i]), db(suff[i + 1]), db(s[i] == ')'), el;
        }
        for (int i = 1; i <= n; i++) {
            if (!((pref[i - 1] + suff[i + 1] + 1) == a[i])) {
                // db(i), db(pref[i - 1]), db(suff[i + 1]), el;
                return false;
            }
        }
        return true;
    };
    int ans = 0;
    for (int i = 0; i < 2; i++) {
        ans += check(i);
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
