代码（正解）：

```c++
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

void solve() {
    int n, m;
    cin >> n >> m;
    vt<int> a(n + 5);
    vt<int> b(m + 5);
    int mx = 0;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        mx = max(mx, a[i]);
    }
    for (int i = 1; i <= m; i++) {
        cin >> b[i];
    }
    vt<int> dis(mx + 5, 1e9), cnt(mx + 5);
    vt<ll> sum(mx + 5);
    for (int i = 1; i <= n; i++) {
        queue<int> q;
        q.push(a[i]);
        dis[a[i]] = 0;
        cnt[a[i]]++;
        vt<int> tmp;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            tmp.pb(u);
            for (int j = 1; j <= m; j++) {
                int v = __gcd(b[j], u);
                if (dis[v] == int(1e9)) {
                    dis[v] = dis[u] + 1;
                    sum[v] += dis[v];
                    cnt[v]++;
                    q.push(v);
                }
            }
        }
        for (auto x : tmp) {
            dis[x] = 1e9;
        }
    }
    ll ans = 1e18;
    for (int i = 1; i <= mx; i++) {
        if (cnt[i] == n) {
            ans = min(ans, sum[i]);
        }
    }
    if (ans == (ll)1e18) {
        cout << "-1\n";
    } else {
        cout << ans << "\n";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
