# 牛客周赛 Round 134

## F

题目链接: https://ac.nowcoder.com/acm/contest/129231/F

思路: 其实这道题我自己想出来了, 但是感觉这个思路有点牛逼, 但是又感觉其实大家都是这个思路, 并没有什么牛逼的地方, 但是就记录一下吧, 就是dp前缀[1...i]有多少种划分方案, 同理dp后缀, 然后枚举满足s[i...j]是回文串的(i, j), 贡献就是(j-i+1)^2\*dp前缀[i-1]\*dp后缀[j+1], 怎么dp和怎么预处理s[i...j]是否是回文串, 这个就看基本功了

代码

```c++
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

const ll MOD=998244353;

ll power(ll u,ll v){
    ll res=1;
    while(v){
        if(v%2) res=res*u%MOD;
        u=u*u%MOD;
        v/=2;
    }
    return res;
}

void add(ll &u,ll v){
    u+=v;
    if(u>=MOD) u-=MOD;
    if(u<0) u+=MOD;
}

ll prod(ll u,ll v){
    return u*v%MOD;
}

void solve(){
    int n;
    cin>>n;
    string s;
    cin>>s;
    s=' '+s;
    auto is_p=[&](string str)->bool{
        for(int i=0,j=sz(str)-1;i<j;i++,j--){
            if(str[i]!=str[j]) return false;
        }
        return true;
    };
    vt<vt<bool>> isp(n+5,vt<bool>(n+5));
    for(int i=1;i<=n;i++){
        string t;
        for(int j=i;j<=n;j++){
            t+=s[j];
            if(is_p(t)){
                isp[i][j]=true;
            }
        }
    }
    vt<ll> dp1(n+5);
    dp1[0]=1;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=i;j++){
            if(isp[j][i]){
                add(dp1[i],dp1[j-1]);
            }
        }
    }
    vt<ll> dp2(n+5);
    dp2[n+1]=1;
    for(int i=n;i>=1;i--){
        for(int j=i;j<=n;j++){
            if(isp[i][j]){
                add(dp2[i],dp2[j+1]);
            }
        }
    }
    ll ans=0;
    for(int i=1;i<=n;i++){
        for(int j=i;j<=n;j++){
            if(isp[i][j]){
                ll len_2=1LL*(j-i+1)*(j-i+1)%MOD;
                add(ans,(len_2*dp1[i-1]%MOD)*dp2[j+1]%MOD);
            }
        }
    }
    cout<<ans<<"\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin>>tt;
    while(tt--){
        solve();
    }
    return 0;
}
