# Codeforces Round 1085 (Div. 1 + Div. 2)

## C

题意: 海里有一个地形, 表示为一个数组a, a[i]表示高度, 然后水位在h这个高度, 可以设置排水沟, 每个单位的水可以向左右下三个方向走, 问在最多设置两个排水沟的情况下, 最多可以排走多少单位的水

思路: 需要注意到, 假设我在列j设置了一个排水沟, 对于第i列, 它的贡献是h - max_a[min(i, j)][max(i, j)], 也就是取决于它们之间的最高地形, 两个排水沟通过容斥原理解决

```cpp
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

void solve() {
    ll n, h;
    cin >> n >> h;
    vt<ll> a(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    vt<vt<ll>> max_a(n + 5, vt<ll>(n + 5));
    for (int i = 1; i <= n; i++) {
        for (int j = i; j <= n; j++) {
            if (i == j) {
                max_a[i][j] = a[i];
            } else {
                max_a[i][j] = max(max_a[i][j - 1], a[j]);
            }
        }
    }
    vt<vt<ll>> pref(n + 5, vt<ll>(n + 5));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            pref[i][j] = pref[i][j - 1] + h - max_a[min(i, j)][max(i, j)];
        }
    }
    vt<vt<ll>> suff(n + 5, vt<ll>(n + 5));
    for (int i = 1; i <= n; i++) {
        for (int j = n; j >= 1; j--) {
            suff[i][j] = suff[i][j + 1] + h - max_a[min(i, j)][max(i, j)];
        }
    }
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        ll cnt = 0;
        for (int j = 1; j <= n; j++) {
            cnt += h - max_a[min(i, j)][max(i, j)];
        }
        ans = max(ans, cnt);
    }
    for (int i = 1; i + 1 <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            ll overlap = pref[j][i] + (j - i - 1) * (h - max_a[i][j]) + suff[i][j];
            ll cnt = pref[i][n] + pref[j][n] - overlap;
            ans = max(ans, cnt);
        }
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

# Codeforces Round 1084 (Div. 3)

## F

题意: 有n个粒子, 每个粒子有两个属性x, y, x是能量值, y是能与之共存的粒子数, 另外商店里面还有m个粒子, 问在买入商店的第i个粒子之后, 最大的能量总值是多少

思路: 假设我们要k个粒子的话, 那么这k个粒子的y都不小于k-1, 我们反向枚举k, 因为k值越小, 候选的粒子数越多, 然后选择x最大的k个粒子, 这样我们就能求出不考虑从商店买粒子的情况下的最大值. 考虑商店, 我们维护一个集合, f[k]表示k个粒子的情况排除掉最小的一个, 给商店的例子腾出一个位置, 商店粒子的可以放在f[1]到f[y+1]的集合里面, 我们要从中选一个最大的, 那么维护一个前缀最大值即可

代码:

```cpp
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

void solve() {
    int n, m;
    cin >> n >> m;
    vt<vt<ll>> adj(n + 5);
    priority_queue<ll, vt<ll>, greater<>> q;
    for (int i = 1; i <= n; i++) {
        ll x, y;
        cin >> x >> y;
        adj[y].push_back(x);
    }
    ll cur = 0;
    for (auto t : adj[n]) {
        q.push(t);
        cur += t;
    }
    while (sz(q) > n + 1) {
        cur -= q.top();
        q.pop();
    }
    vt<ll> pref(n + 5);
    if (sz(q) == n + 1) {
        pref[n + 1] = cur - q.top();
    } else {
        pref[n + 1] = cur;
    }
    vt<ll> cnt(n + 5);
    cnt[n + 1] = cur;
    ll oans = cur;
    for (int k = n; k >= 1; k--) {
        for (auto t : adj[k - 1]) {
            if (sz(q) == k) {
                if (q.top() < t) {
                    cur -= q.top();
                    cur += t;
                    q.pop();
                    q.push(t);
                }
            } else {
                q.push(t);
                cur += t;
            }
        }
        while (sz(q) > k) {
            cur -= q.top();
            q.pop();
        }
        ll t;
        if (sz(q) == k) {
            t = cur - q.top();
        } else {
            t = cur;
        }
        pref[k] = t;
        cnt[k] = cur;
        oans = max(oans, cnt[k]);
    }
    // cout << oans << "\n";
    // for (int i = 1; i <= n + 1; i++) {
    //     cout << pref[i] << " \n"[i == n + 1];
    // }
    for (int i = 2; i <= n + 1; i++) {
        pref[i] = max(pref[i], pref[i - 1]);
    }
    for (int i = 1; i <= m; i++) {
        ll x, y;
        cin >> x >> y;
        // db(x), db(pref[y + 1]), el;
        cout << max(oans, x + pref[y + 1]) << " ";
    }
    cout << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

# Educational Codeforces Round 187 (Rated for Div. 2)

## C

题意: 给定s和m, 要构造一个数列a, 使得$\sum_{i=1}^{n} a_i = s$, 并且对于每个i, $a_i\mathbin{\&}m=a_i$, 求最短的长度n是多少

思路: 这道题肯定和二进制有关, 然后我一开始对着s和m的二进制看, 我发现某些高位的1, 如果m对应的位置是没有的话, 那这个1肯定是由低位的1贡献得来的, 但是要选择哪个1是个问题, 而且有时候不同位置的1, 是可以一起拿的, 这样可以节省一些长度, 这就很难了, 后来问了ai, 是用二分的做法来做的, 很显然, 题目是满足单调性的, 问题是怎么check, 我们可以反过来看m, 当m的第i位为1的时候, 它可以贡献给高位的1, 总共可以贡献s>>i个, 最多拿mid个, 是同一个位的1, 所以必须分到不同的a_i里面, 不同位置的1, 一起拿就好了, 不会影响到其他位置能拿的个数, 为什么这个思路是正确的, 因为n要短的话, a_i要尽可能的大, 我们就希望高位的1出现的越多次越好

代码:

```cpp
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

void solve() {
    ll s, m;
    cin >> s >> m;
    ll lo = 1, hi = 1e18;
    if (s % (m & -m)) {
        cout << "-1\n";
        return;
    }
    auto check = [&](ll mid) -> bool {
        ll ts = s;
        for (int i = 60; i >= 0; i--) {
            if (m >> i & 1) {
                ll t = min(mid, ts >> i);
                ts -= t << i;
            }
        }
        return !ts;
    };
    ll ans = -1;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        if (check(mid)) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
```

