# 牛客2026年除夕娱乐赛

## B

题目链接:https://ac.nowcoder.com/acm/contest/127676/B

思路:分两种情况

下面证明当且仅当哥德巴赫猜想成立时成立

(1) n是偶数
则存在质数p,q使得p+q=n

如果gcd(p,n)==1

0,p,2p,3p,...,(n-1)p,每个都mod n

最后得到的每一个数,将没有重复,这n个数字构成一个模n的完全剩余系,就是{0,1,2,...,n-1}这个集合

每个数都+1,将会得到合法的排列

每个数字之间的差值要么是p,mod n的操作相当于+p-n=-q,也是质数

我需要证明,为什么不会重复

前提: $$\gcd(p,n)=1$$

假设 $$0 \le i < j < n$$，我要证明

$$
ip \not\equiv jp \pmod n
$$

反证法: 假设存在

$$
ip \equiv jp \pmod n
$$

那么

$$
p(j-i) \equiv 0 \pmod n
$$

因为 $$\gcd(n,p)=1$$

所以

$$
(j-i) \bmod n = 0
$$

$$
0 \le i < j < n
$$

$$
0 < j-i < n
$$

n 不可能整除一个小于自己的正整数，所以假设不成立

所以每次+p mod n都会得到一个不一样的数字,n次之后,会得到mod n的完全剩余系

(2) n是奇数
n+1是偶数,同理可以找到质数p+q=n+1

2,4,6,...,n-p

n,n-2,...,1

1+q,1+q+2,...n-1

q=n-p+2

所以是没有问题的

感想:这道题太难了

代码:

```cpp
#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define db(x) cerr << #x << " = " << (x) << " "
#define el cerr << endl
#define vt vector
#define rg(x, a, b) (x).begin() + a, (x).begin() + b + 1
#define sz(x) int((x).size())
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define all(x) (x).begin(), (x).end()
#define fi first
#define se second
#define p_queue priority_queue

vector<int> primes, minp;
void sieve(int n) {
    minp.assign(n + 1, 0);
    for (int i = 2; i <= n; i++) {
        if (minp[i] == 0) {
            primes.push_back(i);
            minp[i] = i;
        }
        for (int p : primes) {
            if (1LL * i * p > n)
                break;
            minp[i * p] = p;
            if (minp[i] == p)
                break;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    sieve(1e5);
    int n;
    cin >> n;
    if (n == 1) {
        cout << "1\n";
    } else if (n <= 3) {
        cout << "-1\n";
    } else if (n == 4) {
        cout << "2 4 1 3\n";
    } else if (n == 6) {
        cout << "1 4 6 3 5 2\n";
    } else {

        vt<int> a(n + 5);
        if (n % 2) {
            int p, q;
            for (auto prime : primes) {
                if (minp[n + 1 - prime] == n + 1 - prime) {
                    p = prime;
                    q = n + 1 - prime;
                    break;
                }
            }
            int idx = 0;
            int cur = 2;
            while (cur <= n - p) {
                a[++idx] = cur;
                cur += 2;
            }
            cur = n;
            while (cur >= 1) {
                a[++idx] = cur;
                cur -= 2;
            }
            cur = q + 1;
            while (cur <= n - 1) {
                a[++idx] = cur;
                cur += 2;
            }
        } else {
            int p;
            for (auto prime : primes) {
                if (minp[n - prime] == n - prime) {
                    p = prime;
                    break;
                }
            }
            a[1] = 0;
            for (int i = 2; i <= n; i++) {
                a[i] = (a[i - 1] + p) % n;
            }
            for (int i = 1; i <= n; i++) {
                a[i]++;
            }
        }
        for (int i = 1; i <= n; i++) {
            cout << a[i] << " \n"[i == n];
        }
    }
    return 0;
}
```

