void solve() {
    int n;
    cin >> n;
    vt<ll> a(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    auto b = a;
    vt<ll> pref(n + 5), suff(n + 5);
    for (int i = 2; i <= n; i++) {
        ll t = min(b[i], b[i - 1]);
        b[i] -= t;
        pref[i] = pref[i - 1] + t;
    }
    b = a;
    for (int i = n - 1; i >= 1; i--) {
        ll t = min(b[i], b[i + 1]);
        b[i] -= t;
        suff[i] = suff[i + 1] + t;
