#define fi first
#define se second
#define p_queue priority_queue

void solve() {
    ll n, m;
    cin >> n >> m;
    vt<string> s(n + 5);
    for (int i = 1; i <= n; i++) {
        cin >> s[i];
        s[i] = ' ' + s[i];
    }
    vt<vt<ll>> col(m + 5, vt<ll>(2));
    for (int j = 1; j <= m; j++) {
        for (int i = 1; i <= n; i++) {
            int c = s[i][j] - '0';
            col[j][c]++;
        }
    }
    for (int i = 1; i <= n; i++) {
        ll ans = 0;
        for (int j = 1; j <= m; j++) {
            int c = s[i][j] - '0';
            ans += col[j][c ^ 1];
        }
        ll prefr = 0;
        ll minl = 0;
        ll sum = ans;
        for (int j = 1; j <= m; j++) {
            int c = s[i][j] - '0';
            ll prefl_1 = prefr;
            minl = min(minl, 2 * prefl_1 + j * (1 - n) + n - 1);
            prefr = prefr + col[j][!c];
            ll curr = -2 * prefr - j * (1 - n);
            ans = min(ans, sum + curr + minl);
        }
        cout << ans << "\n";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
