void solve() {
    int n, m;
    cin >> n >> m;
    vt<vt<ll>> a(n + 5, vt<ll>(m + 5));
    vt<vt<ll>> pref(n + 5, vt<ll>(m + 5));
    int tot = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            cin >> a[i][j];
            if (a[i][j] == 1) {
                tot++;
            }
            pref[i][j] = pref[i][j - 1] + a[i][j];
        }
    }
    int cnt = (tot + 1) / 2;
    vt<vt<vt<bool>>> dp(n + 5, vt<vt<bool>>(m + 5, vt<bool>(cnt + 5)));
    dp[0][0][0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= cnt; j++) {
            for (int j1 = 0; j1 <= m; j1++) {
                for (int j2 = 0; j2 <= j1; j2++) {
                    ll num1 = pref[i][j1];
                    if (j - num1 >= 0) {
                        dp[i][j1][j] = dp[i][j1][j] || dp[i - 1][j2][j - num1];
                    }
                }
            }
        }
    }
    int pre_j, cur_cnt;
    for (int i = m; i >= 0; i--) {
        for (int j = cnt; j >= 0; j--) {
            if (dp[n][i][j]) {
                pre_j = i;
                cur_cnt = j;
                ll ans = 1LL * j * (tot - j);
                cout << ans << "\n";
                goto flag;
            }
        }
    }
    flag:
    vt<int> choose(n + 5);
    choose[n] = pre_j;
    cur_cnt -= pref[n][pre_j];
    for (int i = n - 1; i >= 1; i--) {
        for (int j = pre_j; j >= 0; j--) {
            if (dp[i][j][cur_cnt]) {
                choose[i] = j;
                pre_j = j;
                cur_cnt -= pref[i][j];
                break;
            }
        }
    }
    // for (int i = 1; i <= n; i++) {
    //     db(i), db(choose[i]), el;
    // }
    string ans;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= choose[i] - choose[i - 1]; j++) {
            ans += 'R';
        }
        ans += 'D';
        if (i == n) {
            for (int j = 1; j <= m - choose[i]; j++) {
                ans += 'R';
            }
        }
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        solve();
    }
    return 0;
}
