# 事件发射器

```js
class EventEmitter {
  mp = new Map(); // class里面不能带const或者let
  /**
   * @param {string} eventName
   * @param {Function} callback
   * @return {Object}
   */
  subscribe(eventName, callback) {
    if (!this.mp.has(eventName)) {
      this.mp.set(eventName, [callback]);
    } else {
      this.mp.set(eventName, [...this.mp.get(eventName), callback]);
    }
    return {
      unsubscribe: () => {
        this.mp.set(
          eventName,
          this.mp.get(eventName).filter((item) => {
            if (item == callback) {
              return false;
            }
            return true;
          })
        );
      },
    };
  }

  /**
   * @param {string} eventName
   * @param {Array} args
   * @return {Array}
   */
  emit(eventName, args = []) {
    const funcs = this.mp.get(eventName) || []; // 注意这里可能funcs是空的, 所以或上[]
    let res = [];
    for (const func of funcs) {
      res.push(func(...args));
    }
    return res;
  }
}

/**
 * const emitter = new EventEmitter();
 *
 * // Subscribe to the onClick event with onClickCallback
 * function onClickCallback() { return 99 }
 * const sub = emitter.subscribe('onClick', onClickCallback);
 *
 * emitter.emit('onClick'); // [99]
 * sub.unsubscribe(); // undefined
 * emitter.emit('onClick'); // []
 */
```

