# 并行执行异步函数

```js
/**
 * @param {Array<Function>} functions
 * @return {Promise<any>}
 */
var promiseAll = function (functions) {
  return new Promise((resolve, reject) => {
    if (functions == []) {
      resolve([]);
      return;
    }
    let res = [];
    let resolvedCount = 0;
    functions.forEach(async (func, idx) => {
      try {
        res[idx] = await func();
        if (++resolvedCount == functions.length) {
          resolve(res);
        }
      } catch (err) {
        reject(err);
      }
    });
  });
};

/**
 * const promise = promiseAll([() => new Promise(res => res(42))])
 * promise.then(console.log); // [42]
 */
```

其实 functions == []这个语法是错误的, functions 是对象, 就算它值是[], [] == []还是不一样的, 实际上比较的是引用, 应该用 functions.length == 0 来判断

```js
/**
 * @param {Array<Function>} functions
 * @return {Promise<any>}
 */
var promiseAll = function (functions) {
  return new Promise((resolve, reject) => {
    if (functions.length == 0) {
      resolve([]);
      return;
    }
    let res = [];
    let resolvedCount = 0;
    functions.forEach((func, idx) => {
      func()
        .then((rest) => {
          res[idx] = rest;
          if (++resolvedCount == functions.length) {
            resolve(res);
          }
        })
        .catch((err) => reject(err));
    });
  });
};

/**
 * const promise = promiseAll([() => new Promise(res => res(42))])
 * promise.then(console.log); // [42]
 */
```

这是 then catch 的写法

# 根据 ID 合并两个数组

```js
/**
 * @param {Array} arr1
 * @param {Array} arr2
 * @return {Array}
 */
var join = function (arr1, arr2) {
  arr1.sort((i, j) => i["id"] - j["id"]);
  arr2.sort((i, j) => i["id"] - j["id"]);
  const arr = [];
  let p1 = 0,
    p2 = 0,
    p = 0;
  while (p1 < arr1.length || p2 < arr2.length) {
    if (p1 == arr1.length) {
      arr[p++] = arr2[p2++];
      continue;
    }
    if (p2 == arr2.length) {
      arr[p++] = arr1[p1++];
      continue;
    }
    if (arr1[p1]["id"] == arr2[p2]["id"]) {
      const new_obj = {};
      for (const key in arr2[p2]) {
        new_obj[key] = arr2[p2][key];
      }
      for (const key in arr1[p1]) {
        if (!new_obj.hasOwnProperty(key)) {
          new_obj[key] = arr1[p1][key];
        }
      }
      p1++;
      p2++;
      arr[p++] = new_obj;
    } else if (arr1[p1]["id"] < arr2[p2]["id"]) {
      arr[p++] = arr1[p1++];
    } else {
      arr[p++] = arr2[p2++];
    }
  }
  return arr;
};
```

