```js
const list = [
  { id: 0, name: "根节点", pid: null },
  { id: 1, name: "节点1", pid: 0 },
  { id: 2, name: "节点2", pid: 0 },
  { id: 3, name: "节点1-1", pid: 1 },
  { id: 4, name: "节点1-2", pid: 1 },
  { id: 5, name: "节点2-1", pid: 2 },
  { id: 6, name: "节点2-1-1", pid: 5 },
];

let n = list.length;
const adj = new Array(n);
for (let i = 0; i < n; i++) {
  adj[list[i].id] = {
    id: list[i].id,
    name: list[i].name,
    children: [],
  };
}
let root = null;
for (let i = 0; i < n; i++) {
  const pid = list[i].pid;
  if (pid == null) {
    root = adj[list[i].id];
  } else {
    adj[pid].children.push(adj[list[i].id]);
  }
}
