# 最长不重复子串

```cpp
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int i = 0;
        int n = s.size();
        int j = 0;
        vector<int> cnt(114514);
        int mxlen = 0;
        while (i < n) {
            j = max(j, i);
            while (j < n && cnt[s[j]] == 0) {
                cnt[s[j]]++;
                j++;
            }
            // [i, j - 1]
            int len = j - i;
            if (len > mxlen) {
                mxlen = len;
            }
            cnt[s[i]]--;
            i++;
        }
        return mxlen;
    }
};
```

思路很简单啦，就是双指针，注意一下右端点的含义就行

